const competitors = $("Load Competitors").all().map(i => i.json);
const cfgRow = $("Load SOV Config").first();
const config = (cfgRow && cfgRow.json && cfgRow.json.config) ? cfgRow.json.config : {};
const active = competitors.filter(c => c.active !== false);
const companies = active.map(c => ({ name: c.name, aliases: Array.isArray(c.aliases) ? c.aliases : [], domain: c.domain || null, x_handle: c.x_handle || null, linkedin_urn: c.linkedin_urn || null, subreddits: Array.isArray(c.subreddits) ? c.subreddits : [], type: c.type || 'direct' }));
const linkedin_urns = companies.map(c => c.linkedin_urn).filter(Boolean);
const companyEnum = companies.map(c => c.name).join(", ");
const allSubreddits = Array.from(new Set([].concat(...companies.map(c => c.subreddits)).concat(["cybersecurity","netsec","asknetsec","devsecops","hacking","information_security","security","identitymanagement","sysadmin","itmanagers","blueteamsec"]))).filter(Boolean);
return [{ json: { config, companies, linkedin_urns, companyEnum, allSubreddits } }];

// Compute SOV Snapshot — dual-write (sov_weekly unchanged + rolling 7d/30d -> sov_daily).
// 2026-07-06: sov_daily now RE-DERIVES the trailing 8 days each run (not just today), so
// weekly-cadence platforms (Reddit/X/News) that land in a batch backfill onto their real
// post dates -> smooth daily curve, no Thursday sawtooth. DB-only; still 1 execution/day.
// 2026-07-08 (OOM fix v2): aggregation moved SERVER-SIDE to the Postgres RPC sov_board_agg.
// 2026-07-08 (MINDSHARE MODEL): score(c) = Σ_platform mult[platform] × wsum(c,platform);
//   weighted_pct(c) = 100 × score(c) / Σ score over DIRECT companies.
// 2026-07-12 (CUMULATIVE DAILY): each re-derived day ALSO gets an end-of-day all-time
//   cumulative board written to sov_daily with window_days=0 (reuses computeBoard(null,asOf)).
const helpers = this.helpers;
const SRK = '<REDACTED_SUPABASE_JWT>';
const SB = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H = { apikey: SRK, Authorization: 'Bearer ' + SRK };

const ctx = $('Build Context').first().json; const cfg = ctx.config || {};
const comps = ctx.companies || [];
const allNames = comps.map(c => c.name).filter(Boolean);
const allNameSet = new Set(allNames);
const directSet = new Set(comps.filter(c => (c.type || 'direct') !== 'indirect').map(c => c.name));
const platformMultipliers = cfg.platformMultipliers || { LinkedIn:1, 'Google News':30, Reddit:3, X:1 };
const overallW = cfg.overallWeights || { unweighted:0.20, weighted:0.80, sentiment:0.0 };
const enabled = new Set(Array.isArray(cfg.enabledPlatforms) ? cfg.enabledPlatforms : ['LinkedIn','Google News','Reddit','X']);

const NOW = Date.now();
const platformKeys = ['LinkedIn','Google News','Reddit','X'].filter(p => enabled.has(p));

// windowDays=null -> all-time as-of asOfMs (or NOW). windowDays + asOfMs -> trailing window.
async function computeBoard(windowDays, asOfMs) {
  const as_of = new Date(asOfMs != null ? asOfMs : Date.now()).toISOString();
  const window_days = (windowDays != null ? windowDays : null);
  let aggRows;
  try {
    aggRows = await helpers.httpRequest({ method:'POST', url: SB + '/rpc/sov_board_agg', headers: Object.assign({}, H, { 'Content-Type':'application/json' }), body: { as_of: as_of, window_days: window_days }, json:true });
  } catch (e) { aggRows = []; }
  const agg = {};
  for (const platform of platformKeys) { agg[platform] = {}; }
  for (const row of (Array.isArray(aggRows) ? aggRows : [])) {
    const platform = row.platform;
    if (!agg[platform]) continue;               // platform not enabled -> skip
    const name = row.company;
    if (!name || name === 'NONE') continue;
    if (!allNameSet.has(name)) continue;
    const pw = Number(row.wsum); if (!isFinite(pw)) continue;
    const cnt = Number(row.cnt) || 0;
    if (!agg[platform][name]) agg[platform][name] = { pw:0, cntw:0, count:0, sentSum:0, sentCount:0 };
    const A = agg[platform][name];
    A.pw += pw; A.cntw += cnt; A.count += cnt;
    A.sentSum += (Number(row.sent_sum) || 0); A.sentCount += (Number(row.sent_cnt) || 0);
  }

  // MINDSHARE: score(c) = Σ_platform mult[platform] × pw(c,platform); denom = DIRECT companies.
  const scoreBy = {}; let directScoreSum = 0;
  for (const p of platformKeys) {
    const m = (platformMultipliers[p] != null && isFinite(Number(platformMultipliers[p]))) ? Number(platformMultipliers[p]) : 1;
    for (const name of Object.keys(agg[p])) {
      scoreBy[name] = (scoreBy[name] || 0) + m * agg[p][name].pw;
    }
  }
  for (const name of Object.keys(scoreBy)) { if (directSet.has(name)) directScoreSum += scoreBy[name]; }

  let grandCntw = 0; const cntwBy = {}; const cntBy = {}; const sentSumBy = {}; const sentCntBy = {};
  for (const platform of platformKeys) {
    for (const name of Object.keys(agg[platform])) {
      const A = agg[platform][name];
      cntwBy[name] = (cntwBy[name] || 0) + A.cntw;
      cntBy[name]  = (cntBy[name]  || 0) + A.count;
      sentSumBy[name] = (sentSumBy[name] || 0) + A.sentSum;
      sentCntBy[name] = (sentCntBy[name] || 0) + A.sentCount;
      if (directSet.has(name)) grandCntw += A.cntw;
    }
  }

  const rows = [];
  for (const name of allNames) {
    const score = scoreBy[name] || 0;
    const weighted_pct = parseFloat((directScoreSum > 0 ? (score / directScoreSum) * 100 : 0).toFixed(4));
    const unweighted_pct = parseFloat((grandCntw > 0 ? ((cntwBy[name] || 0) / grandCntw) * 100 : 0).toFixed(4));
    const avgSent = (sentCntBy[name] > 0) ? (sentSumBy[name] / sentCntBy[name]) : 0;
    const sentiment_pct = parseFloat((((avgSent + 3) / 6) * 100).toFixed(4));
    const overall = parseFloat((((overallW.weighted!=null?overallW.weighted:0.80) * weighted_pct) + ((overallW.unweighted!=null?overallW.unweighted:0.20) * unweighted_pct) + ((overallW.sentiment!=null?overallW.sentiment:0.0) * sentiment_pct)).toFixed(4));
    rows.push({ company: name, overall, weighted_pct, unweighted_pct, sentiment_pct, posts_count: (cntBy[name] || 0) });
  }
  return rows;
}

function isoThursday(d){ const dt = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())); const back = (dt.getUTCDay() - 4 + 7) % 7; dt.setUTCDate(dt.getUTCDate() - back); return dt.toISOString().slice(0,10); }
const week_start = isoThursday(new Date());
const weeklyMetrics = await computeBoard(null);
const weeklyRows = weeklyMetrics.map(r => Object.assign({ week_start }, r));

const snapshot_date = new Date(NOW).toISOString().slice(0,10);
const DAY = 86400000;
const EPOCH = '2026-06-22';  // clean-history start — never write pre-model days
const dailySummary = {};
// Re-derive the trailing 8 days each run (7d window + 1 edge day) so weekly-cadence
// data backfills onto its true dates. i=0 reproduces today's row exactly (as-of NOW).
for (let i = 0; i < 8; i++) {
  const asOfMs = NOW - i * DAY;
  const snap_date = new Date(asOfMs).toISOString().slice(0,10);
  if (snap_date < EPOCH) continue;
  for (const wd of [7, 30]) {
    try {
      const m = await computeBoard(wd, asOfMs);
      const dailyRows = m.map(r => ({ snapshot_date: snap_date, company: r.company, window_days: wd, overall: r.overall, weighted_pct: r.weighted_pct, sentiment_pct: r.sentiment_pct, posts_count: r.posts_count }));
      await helpers.httpRequest({ method: 'POST', url: SB + '/sov_daily?on_conflict=snapshot_date,company,window_days', headers: Object.assign({}, H, { 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' }), body: dailyRows, json: true });
      dailySummary[snap_date + '_w' + wd] = dailyRows.length;
    } catch (e) { dailySummary[snap_date + '_w' + wd] = 'ERR: ' + (e && e.message ? e.message : e); }
  }
  // window_days=0 = all-time CUMULATIVE board as-of END-OF-DAY D (23:59:59.999 UTC),
  // so a daily-cumulative standings series accumulates going forward (frontend trend line).
  // Reuses the SAME computeBoard(null, asOf) path as the weekly/all-time board
  // (window_days=null at the RPC = all-time as-of). Written with window_days=0 so it
  // coexists with the 7/30 rows under the same on_conflict key.
  try {
    const endOfDayMs = Date.parse(snap_date + 'T23:59:59.999Z');
    const m0 = await computeBoard(null, endOfDayMs);
    const cumRows = m0.map(r => ({ snapshot_date: snap_date, company: r.company, window_days: 0, overall: r.overall, weighted_pct: r.weighted_pct, sentiment_pct: r.sentiment_pct, posts_count: r.posts_count }));
    await helpers.httpRequest({ method: 'POST', url: SB + '/sov_daily?on_conflict=snapshot_date,company,window_days', headers: Object.assign({}, H, { 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' }), body: cumRows, json: true });
    dailySummary[snap_date + '_w0'] = cumRows.length;
  } catch (e) { dailySummary[snap_date + '_w0'] = 'ERR: ' + (e && e.message ? e.message : e); }
}

return [{ json: { week_start, snapshot_date, rows: weeklyRows, sov_daily: dailySummary } }];

// === Freshness Guard (n8n Code node, Run Once for All Items) ===
// Runs AFTER Build Context and BEFORE Compute SOV Snapshot on the SNAPSHOT path.
// Ensures we never re-publish a STALE board. Daily model: LinkedIn is the daily
// signal (must be fresh); News is WEEKLY by design so it gets a wider tolerance.
// If LinkedIn is stale/absent (or News is ancient), throw + abort before Compute.
const helpers = this.helpers;
const KEY = '<REDACTED_SUPABASE_JWT>';
const BASE = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H = { apikey: KEY, Authorization: 'Bearer ' + KEY };

const THRESHOLD_DAYS = 8;       // LinkedIn: daily scrape -> should always be <2d
const NEWS_THRESHOLD_DAYS = 10; // News is weekly by design -> tolerate a full cycle + article lag

function ageDays(t) { if (!t) return null; const d = new Date(t); return isNaN(d) ? null : Math.max(0, (Date.now() - d.getTime()) / 86400000); }

async function newest(table, tsCol) {
  let arr;
  try {
    arr = await helpers.httpRequest({
      method: 'GET',
      url: BASE + '/' + table + '?select=' + tsCol + '&order=' + tsCol + '.desc.nullslast&limit=1',
      headers: H,
      json: true,
    });
  } catch (e) {
    throw new Error('Freshness Guard: failed reading ' + table + ' (' + (e && e.message ? e.message : e) + ') — aborting snapshot (fail closed)');
  }
  const rows = Array.isArray(arr) ? arr : [];
  if (!rows.length) return { ts: null, age: null };
  const ts = rows[0][tsCol];
  return { ts: ts, age: ageDays(ts) };
}

const li = await newest('linkedin_posts', 'posted_at');
const gn = await newest('googlenews', 'publishedAt');

console.log('Freshness Guard: LinkedIn newest posted_at=' + li.ts + ' (age ' + (li.age == null ? 'n/a' : li.age.toFixed(2)) + 'd, thr ' + THRESHOLD_DAYS + 'd), News newest publishedAt=' + gn.ts + ' (age ' + (gn.age == null ? 'n/a' : gn.age.toFixed(2)) + 'd, thr ' + NEWS_THRESHOLD_DAYS + 'd)');

if (li.age == null || li.age > THRESHOLD_DAYS) {
  throw new Error('Freshness Guard: LinkedIn data stale/absent (newest=' + li.ts + ') — aborting snapshot to avoid a stale board');
}
if (gn.age == null || gn.age > NEWS_THRESHOLD_DAYS) {
  throw new Error('Freshness Guard: News data stale/absent (newest=' + gn.ts + ') — aborting snapshot to avoid a stale board');
}

// Both fresh -> pass input through unchanged.
return $input.all();
